// Cleanup worker. An earlier version of this site (Jekyll + Chirpy) registered
// a service worker at this URL that cached every page. This replacement takes
// over, deletes those caches, unregisters itself, and reloads open tabs so
// returning visitors get the current site. Safe to delete after a few months.
self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", event => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map(key => caches.delete(key)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: "window" });
      clients.forEach(client => client.navigate(client.url));
    })()
  );
});
